CREATE TABLE upload_sessions (id TEXT PRIMARY KEY, upload_key TEXT UNIQUE NOT NULL, file_name TEXT NOT NULL, mime_type TEXT, total_size BIGINT NOT NULL, chunk_size BIGINT NOT NULL, chunk_count INT NOT NULL, status TEXT NOT NULL, expected_checksum TEXT, actual_checksum TEXT, storage_root TEXT NOT NULL, uploaded_by TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, expired_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, failure_reason TEXT);
CREATE TABLE chunk_records (session_id TEXT NOT NULL REFERENCES upload_sessions(id) ON DELETE CASCADE, chunk_index INT NOT NULL, size BIGINT NOT NULL, sha256 TEXT NOT NULL, stored_path TEXT NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(session_id, chunk_index));
CREATE TABLE file_records (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL REFERENCES upload_sessions(id), name TEXT NOT NULL, size BIGINT NOT NULL, sha256 TEXT NOT NULL, chunk_count INT NOT NULL, mime_type TEXT, status TEXT NOT NULL, download_count BIGINT NOT NULL DEFAULT 0, uploaded_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, stored_path TEXT NOT NULL);
CREATE TABLE upload_session_events (id BIGSERIAL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES upload_sessions(id) ON DELETE CASCADE, from_status TEXT, to_status TEXT NOT NULL, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
